; front_201CD_bss_01 158CBA-158F24  NHL 96 PC HOCKEY.EXE dseg04
; Zero-filled state of the joystick test and GrIP pad setup screens.
; generated by tools/build/gen_src.py, assembled by ./build.sh (see docs/ASM_BUILD.md)
bits 32
%include "hockey.inc"
section s_158CBA nobits alloc noexec write align=1
global GripSetupSlots, JoyTestBmps, JoyTestDotX, JoyTestDotY, JoyTestArt
global GripSetupLastBits, JoyTestLastTick, JoyTestFrame, GripSetupTick, GripSetupCursor, GoalLightLamp, RinkModelBoards, GoalLightTimerFar
global RinkModelGlass, GoalLightFrame, FarSideModel, GoalLightOn, RinkModelIce, IcePolyBuffer, JoyTestButtonsLit, JoyTestAxisVals
global GripSetupHeld, GripSetupCounts, GripSetupTimers, LastButtonCode, GripSetupSlot
JoyTestButtonsLit:                              ; Joystick test screen: lit flag per button; used by
                                                ; JoystickTestScreen, UpdateJoystickTest
        resb 2
JoyTestAxisVals:                                ; Joystick test screen: axis values shown; used by
                                                ; UpdateJoystickTest
        resb 4
JoyTestBmps:                                    ; Joystick test screen: bitmaps; used by JoystickTestScreen
        resb 12
JoyTestDotX:                                    ; Joystick test screen: x of the stick dot; used by
                                                ; JoystickTestScreen, UpdateJoystickTest
        resb 4
JoyTestDotY:                                    ; Joystick test screen: y of the stick dot; used by
                                                ; JoystickTestScreen, UpdateJoystickTest
        resb 4
JoyTestArt:                                     ; Joystick test screen: art pieces; used by JoystickTestScreen
        resb 86
GripSetupSlots:                                 ; GrIP set-up screen: per-slot state bytes; used by
                                                ; DrawGripPads, GripSetupScreen
        resb 1
        resb 1
        resb 1
        resb 7
GripSetupHeld:                                  ; GrIP set-up screen: button held per slot; used by
                                                ; DrawGripPads, GripSetupScreen
        resb 8
GripSetupCounts:                                ; GrIP set-up screen: press counts per slot; used by
                                                ; DrawGripPads, GripSetupScreen
        resb 8
GripSetupTimers:                                ; GrIP set-up screen: timers per slot; used by DrawGripPads,
                                                ; GripSetupScreen
        resb 2
        resb 14
GripSetupLastBits:                              ; GrIP set-up screen: last pad bits per slot; used by
                                                ; DrawGripPads, GripSetupScreen
        resb 16
JoyTestLastTick:                                ; Joystick test screen: tick of the last update; used by
                                                ; JoystickTestScreen, UpdateJoystickTest
        resb 4
JoyTestFrame:                                   ; Joystick test screen: frame counter; used by
                                                ; JoystickTestScreen, UpdateJoystickTest
        resb 4
GripSetupTick:                                  ; GrIP set-up screen: tick of the last update; used by
                                                ; GripSetupScreen
        resb 4
GripSetupCursor:                                ; GrIP set-up screen: cursor; used by DrawGripPads,
                                                ; GripSetupScreen
        resb 4
LastButtonCode:                                 ; Last button code seen by the set-up screen and the goal
                                                ; light start; used by GripSetupScreen, StartGoalLight
        resb 2
GripSetupSlot:                                  ; GrIP set-up screen: slot being set up; used by DrawGripPads,
                                                ; GripSetupScreen
        resb 2
GoalLightLamp:                                  ; Goal light: lamp state drawn by DrawGoalLight; used by
                                                ; DrawGoalLight, UpdateGoalLight
        resb 4
RinkModelBoards:                                ; Rink model: board pieces; used by LoadRinkModel
        resb 8
GoalLightTimerFar:                              ; goal light timer, far net; used by UpdateGoalLight
        resb 4
RinkModelGlass:                                 ; Rink model: glass pieces; used by LoadRinkModel
        resb 8
GoalLightFrame:                                 ; goal light frame; used by UpdateGoalLight
        resb 4
FarSideModel:                                   ; far side model; used by LoadRinkModel
        resb 8
GoalLightOn:                                    ; goal light on; used by UpdateGoalLight
        resb 4
RinkModelIce:                                   ; Rink model: ice pieces; used by LoadRinkModel
        resb 8
IcePolyBuffer:                                  ; Ice surface polygon buffer (DrawIceSurface,
                                                ; DrawFaceoffCircle); used by DrawFaceoffCircle,
                                                ; DrawIceSurface
        resb 380
